/** Independent visible SVG/p-u/ol geometry reader, no producer model import. */
import assert from'node:assert/strict';import review from'./legacy-2017-pm4-review.json';const decode=(s:string)=>s.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#x27;/g,"'");const strip=(s:string)=>decode(s.replace(/<[^>]*>/g,''));function a(s:string,k:string){const m=s.match(new RegExp('(?:^|\\s)'+k+'="([^"]*)"'));assert(m,k);return decode(m[1]);}
export function readLegacy2017Pm4Figure(svg:string){assert(!/<script\b/.test(svg));assert.equal(a(svg.match(/<svg\b([^>]*)>/)![1],'viewBox'),'0 0 1000 260');const rects=[...svg.matchAll(/<rect\b([^>]*)>/g)].map(m=>['x','y','width','height'].map(k=>Number(a(m[1],k))));assert.deepEqual(rects,[[140,20,140,80],[280,20,110,80],[390,20,250,80],[810,20,100,80],[640,140,90,80],[730,140,80,80]]);const paths=[...svg.matchAll(/<path\b([^>]*)>/g)].map(m=>a(m[1],'d'));assert.deepEqual(paths,['M640 60H810 M140 180H640 M810 180H965','M910 20H965Q975 40 965 60Q955 80 965 100H910Z','M505 108H535V145H550L520 175L490 145H505Z','M755 128H785V90H800L770 65L740 90H755Z','M920 108H950V145H965L935 175L905 145H920Z']);const texts=[...svg.matchAll(/<text\b([^>]*)>([\s\S]*?)<\/text>/g)].map(m=>({x:Number(a(m[1],'x')),y:Number(a(m[1],'y')),text:strip(m[2])}));assert.deepEqual(texts,[{x:65,y:70,text:'送信側機器'},{x:65,y:188,text:'受信側機器'},{x:210,y:70,text:'(2)待機'},{x:335,y:53,text:'(3)W1'},{x:335,y:80,text:'待機'},{x:515,y:70,text:'(4)データフレーム送信'},{x:860,y:70,text:'(3)'},{x:937,y:70,text:'(4)'},{x:685,y:172,text:'(6)W2'},{x:685,y:200,text:'待機'},{x:770,y:163,text:'(6)ACK'},{x:770,y:187,text:'フレーム'},{x:770,y:211,text:'送信'},{x:15,y:250,text:'注記 矢印はフレームの送信方向を表す。'}]);assert(svg.includes('<figcaption>図1 データフレーム送信の例</figcaption>'));const desc=strip(svg.match(/<desc[^>]*>([\s\S]*?)<\/desc>/)![1]);assert.equal(desc,'図1 データフレーム送信の例。送信側と受信側の2本の時系列。送信側は(2)待機、(3)W1待機、(4)データフレーム送信の順。受信側は(6)W2待機、(6)ACKフレーム送信の順。ACK後に送信側の(3)、(4)が続く。3本の中空矢印の向きは、データが送信側から受信側、ACKが受信側から送信側、次のデータが送信側から受信側。注記：矢印はフレームの送信方向を表す。');for(const phrase of ['2本','3本','送信側から受信側','受信側から送信側','W1','W2','ACK','矢印はフレームの送信方向'])assert(desc.includes(phrase));assert(/<g fill="none" stroke="currentColor">/.test(svg));return{timelines:2,hollowArrows:3,rectangles:6,wavyContinuation:1,visibleTextSegments:texts.length,noteVisible:true,captionVisible:true};}
export function readLegacy2017Pm4Text(html:string){const u=review.original.units.find(u=>u.id==='comparison')!;assert(!/<script\b/.test(html));assert.equal(strip(html),u.text);const spans=[...html.matchAll(/<u\b([^>]*)>([\s\S]*?)<\/u>/g)];assert.deepEqual(spans.map(m=>strip(m[2])),u.underlined);for(const m of spans){assert(a(m[1],'style').includes('text-decoration-line:underline'));assert(a(m[1],'style').includes('text-decoration-style:solid'));assert(a(m[1],'style').includes('text-decoration-skip-ink:none'));}return{underlines:2,fullParagraph:true};}
export function readLegacy2017Pm4List(html:string,id:'flow'|'techniques'){const u=review.original.units.find(u=>u.id===id)!;assert(html.startsWith('<ol '));assert(!/<script\b/.test(html));const items=[...html.matchAll(/<li\b[^>]*>([\s\S]*?)<\/li>/g)].map(m=>strip(m[1]));assert.deepEqual(items,u.items!.map((text,i)=>u.sourceMarkers![i]+text));const marks=[...html.matchAll(/<span data-pm4-list-marker="1">([^<]+)<\/span>/g)].map(m=>decode(m[1]));assert.deepEqual(marks,u.sourceMarkers);return{items:items.length,ordered:true,markers:marks};}
